class JobService:
    def cancel(self, job_id):
        changed = self.repository.transition(job_id, 'QUEUED', 'CANCELLED')
        return changed == 1

    def claim(self, job_id):
        changed = self.repository.transition(job_id, 'QUEUED', 'RUNNING')
        return changed == 1

class JobRepository:
    def transition(self, job_id, from_state, to_state):
        sql = 'UPDATE jobs SET state = %s WHERE id = %s AND state = %s'
        result = self.db.execute(sql, (to_state, job_id, from_state))
        return result.rowcount

class JobService:
    def submit(self, payload):
        job = Job(id=new_id(), payload=payload, state='QUEUED')
        self.store.insert(job)
        self.dispatcher.enqueue(job.id)
        return job

    def execute(self, job_id):
        job = self.store.find(job_id)
        if job.state != 'QUEUED':
            return
        if not self.store.compare_and_set_state(job_id, 'QUEUED', 'RUNNING'):
            return
        try:
            self.runner.run(job.payload)
        except Exception:
            self.store.update_state(job_id, 'FAILED')
            return
        self.store.update_state(job_id, 'SUCCEEDED')

class RetryWorker:
    def run(self, job):
        attempt = job.attempts + 1
        self.store.update_attempt_and_state(job.id, attempt, 'RUNNING')
        try:
            self.executor.execute(job.payload)
        except Exception as exc:
            if attempt < job.max_attempts:
                due = self.clock.now() + self.backoff.delay(attempt)
                self.store.update_retry(job.id, attempt, 'RETRY_WAIT', due)
                self.retry_queue.schedule(job.id, due)
            else:
                self.store.update_failure(job.id, attempt, 'FAILED', str(exc))
            return
        self.store.update_state(job.id, 'SUCCEEDED')
